import React, { useState } from 'react';
import ReactDOM from 'react-dom';
import {
  OverflowMenu,
  OverflowMenuItem,
  Button,
  ComposedModal,
  ModalHeader,
  ModalBody,
  ModalFooter,
} from 'carbon-components-react';
import 'carbon-components/css/carbon-components.min.css';

function App() {
  const [open, setOpen] = useState(false);
  return (
    // Switch between "g90" and "g100" to test each theme
    <div data-carbon-theme="g90" style={{ padding: '2rem', background: '#2d2d2d', minHeight: '100vh' }}>
      {/*
        Override the default overflow-menu shadow and modal overlay
        for dark themes to reproduce the bug and test the fix.
      */}
      <style>{`
        /* OverflowMenu shadow overrides */
        [data-carbon-theme="g90"] .bx--overflow-menu-options {
          /* proposed: 70% opacity */
          box-shadow: 0 2px 6px 0 rgba(0, 0, 0, 0.7) !important;
        }
        [data-carbon-theme="g100"] .bx--overflow-menu-options {
          /* proposed: 80% opacity */
          box-shadow: 0 2px 6px 0 rgba(0, 0, 0, 0.8) !important;
        }
        /* Modal overlay override */
        [data-carbon-theme="g90"] .bx--modal-backdrop,
        [data-carbon-theme="g100"] .bx--modal-backdrop {
          background-color: rgba(0, 0, 0, 0.65) !important;
        }
      `}</style>

      <h2 style={{ color: '#fff' }}>OverflowMenu Shadow & Modal Overlay Test (G90)</h2>

      <table className="bx--data-table" style={{ background: '#3a3a3a', width: '100%' }}>
        <tbody>
          <tr>
            <td style={{ color: '#fff', padding: '1rem' }}>cell text</td>
            <td style={{ padding: '1rem' }}>
              <OverflowMenu ariaLabel="open menu">
                <OverflowMenuItem itemText="Option 1" />
                <OverflowMenuItem itemText="Option 2" />
                <OverflowMenuItem itemText="Option 3" />
              </OverflowMenu>
            </td>
          </tr>
        </tbody>
      </table>

      <div style={{ marginTop: '2rem' }}>
        <Button kind="primary" onClick={() => setOpen(true)}>
          Open Modal
        </Button>
      </div>

      <ComposedModal open={open} onClose={() => setOpen(false)}>
        <ModalHeader>Transactional modal title</ModalHeader>
        <ModalBody>
          <p style={{ margin: 0 }}>
            Lorem ipsum dolor sit amet, consectetur adipiscing elit. Sed do eiusmod tempor incididunt ut labore et dolore magna aliqua.
          </p>
        </ModalBody>
        <ModalFooter primaryButtonText="Save" secondaryButtonText="Cancel" />
      </ComposedModal>
    </div>
  );
}

ReactDOM.render(<App />, document.getElementById('root'));
